'use strict';

const fs = require('node:fs');

// An error caused by user input or a bad data file. The CLI prints these
// as a one-line message instead of a stack trace.
class TodoError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TodoError';
  }
}

function loadTodos(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }

  if (raw.trim() === '') return [];

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${file} is not valid JSON; fix or remove it and try again`);
  }

  const isTodoList =
    Array.isArray(data) &&
    data.every((todo) => todo !== null && typeof todo === 'object' && Number.isSafeInteger(todo.id));
  if (!isTodoList) {
    throw new TodoError(`${file} does not contain a list of todos; fix or remove it and try again`);
  }
  return data;
}

function saveTodos(file, todos) {
  // Write to a temp file and rename it into place so an interrupted write
  // can't leave a truncated todos.json behind.
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, `${JSON.stringify(todos, null, 2)}\n`);
  fs.renameSync(tmp, file);
}

function nextId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
}

function findTodo(todos, id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) throw new TodoError(`Todo #${id} not found`);
  return todo;
}

function addTodo(file, text, now = new Date()) {
  const trimmed = typeof text === 'string' ? text.trim() : '';
  if (trimmed === '') throw new TodoError('Todo text cannot be empty');

  const todos = loadTodos(file);
  const todo = {
    id: nextId(todos),
    text: trimmed,
    completed: false,
    createdAt: now.toISOString(),
  };
  todos.push(todo);
  saveTodos(file, todos);
  return todo;
}

// Returns { todo, changed }; changed is false if the todo was already done.
function completeTodo(file, id) {
  const todos = loadTodos(file);
  const todo = findTodo(todos, id);
  if (todo.completed) return { todo, changed: false };

  todo.completed = true;
  saveTodos(file, todos);
  return { todo, changed: true };
}

function deleteTodo(file, id) {
  const todos = loadTodos(file);
  const todo = findTodo(todos, id);
  saveTodos(file, todos.filter((t) => t !== todo));
  return todo;
}

module.exports = { TodoError, loadTodos, saveTodos, addTodo, completeTodo, deleteTodo };

