'use strict';

const { describe, test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { TodoError, loadTodos, saveTodos, addTodo, completeTodo, deleteTodo } = require('../todos');

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todos-unit-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

const readRaw = () => JSON.parse(fs.readFileSync(file, 'utf8'));

describe('loadTodos', () => {
  test('returns an empty list when the file does not exist', () => {
    assert.deepEqual(loadTodos(file), []);
  });

  test('returns an empty list when the file is empty or whitespace', () => {
    fs.writeFileSync(file, '');
    assert.deepEqual(loadTodos(file), []);
    fs.writeFileSync(file, '  \n\t');
    assert.deepEqual(loadTodos(file), []);
  });

  test('returns the stored todos', () => {
    const todos = [{ id: 1, text: 'a', completed: false, createdAt: '2026-01-01T00:00:00.000Z' }];
    fs.writeFileSync(file, JSON.stringify(todos));
    assert.deepEqual(loadTodos(file), todos);
  });

  test('throws a TodoError for invalid JSON', () => {
    fs.writeFileSync(file, '{not json');
    assert.throws(() => loadTodos(file), { name: 'TodoError', message: /not valid JSON/ });
  });

  test('throws a TodoError when the JSON is not an array', () => {
    fs.writeFileSync(file, '{"id": 1}');
    assert.throws(() => loadTodos(file), { name: 'TodoError', message: /list of todos/ });
  });

  test('throws a TodoError when an entry has no integer id', () => {
    for (const bad of [[null], ['text'], [{ text: 'no id' }], [{ id: '1' }], [{ id: 1.5 }]]) {
      fs.writeFileSync(file, JSON.stringify(bad));
      assert.throws(() => loadTodos(file), TodoError, `expected ${JSON.stringify(bad)} to be rejected`);
    }
  });

  test('rethrows filesystem errors other than a missing file', () => {
    // Reading a directory fails with EISDIR, which is not a "no todos yet" case.
    assert.throws(() => loadTodos(dir), (err) => !(err instanceof TodoError) && err.code === 'EISDIR');
  });
});

describe('saveTodos', () => {
  test('round-trips through loadTodos', () => {
    const todos = [
      { id: 1, text: 'a', completed: true, createdAt: '2026-01-01T00:00:00.000Z' },
      { id: 3, text: 'b', completed: false, createdAt: '2026-01-02T00:00:00.000Z' },
    ];
    saveTodos(file, todos);
    assert.deepEqual(loadTodos(file), todos);
  });

  test('does not leave temporary files behind', () => {
    saveTodos(file, []);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });
});

describe('addTodo', () => {
  test('creates a todo with id, text, completed and createdAt', () => {
    const now = new Date('2026-09-30T12:34:56.789Z');
    const todo = addTodo(file, 'Buy groceries', now);

    assert.deepEqual(todo, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-09-30T12:34:56.789Z',
    });
    assert.deepEqual(readRaw(), [todo]);
  });

  test('defaults createdAt to the current time', () => {
    const before = Date.now();
    const todo = addTodo(file, 'Now');
    const after = Date.now();

    const created = Date.parse(todo.createdAt);
    assert.ok(created >= before && created <= after, `${todo.createdAt} not within test window`);
  });

  test('assigns auto-incrementing ids', () => {
    assert.equal(addTodo(file, 'one').id, 1);
    assert.equal(addTodo(file, 'two').id, 2);
    assert.equal(addTodo(file, 'three').id, 3);
  });

  test('never reuses the id of a surviving todo after a deletion', () => {
    addTodo(file, 'one');
    addTodo(file, 'two');
    addTodo(file, 'three');
    deleteTodo(file, 1);

    assert.equal(addTodo(file, 'four').id, 4);
  });

  test('trims surrounding whitespace from the text', () => {
    assert.equal(addTodo(file, '   Walk the dog  ').text, 'Walk the dog');
  });

  test('rejects empty, whitespace-only and non-string text without writing', () => {
    for (const text of ['', '   ', undefined, null, 42]) {
      assert.throws(() => addTodo(file, text), { name: 'TodoError', message: /cannot be empty/ });
    }
    assert.equal(fs.existsSync(file), false);
  });
});

describe('completeTodo', () => {
  test('marks the todo as completed and persists it', () => {
    addTodo(file, 'one');
    addTodo(file, 'two');

    const { todo, changed } = completeTodo(file, 2);

    assert.equal(changed, true);
    assert.equal(todo.completed, true);
    assert.deepEqual(
      readRaw().map((t) => t.completed),
      [false, true]
    );
  });

  test('reports no change for an already completed todo', () => {
