describe('loadTodos', () => {
  test('returns an empty list when the file does not exist', () => {
    assert.deepEqual(loadTodos(file), []);
  });

  test('returns an empty list when the file is empty or whitespace', () => {
    fs.writeFileSync(file, '');
    assert.deepEqual(loadTodos(file), []);
    fs.writeFileSync(file, '  \n\t');
    assert.deepEqual(loadTodos(file), []);
  });

  test('returns the stored todos', () => {
    const todos = [{ id: 1, text: 'a', completed: false, createdAt: '2026-01-01T00:00:00.000Z' }];
    fs.writeFileSync(file, JSON.stringify(todos));
    assert.deepEqual(loadTodos(file), todos);
  });

  test('throws a TodoError for invalid JSON', () => {
    fs.writeFileSync(file, '{not json');
    assert.throws(() => loadTodos(file), { name: 'TodoError', message: /not valid JSON/ });
  });

  test('throws a TodoError when the JSON is not an array', () => {
    fs.writeFileSync(file, '{"id": 1}');
    assert.throws(() => loadTodos(file), { name: 'TodoError', message: /list of todos/ });
  });

  test('throws a TodoError when an entry has no integer id', () => {
    for (const bad of [[null], ['text'], [{ text: 'no id' }], [{ id: '1' }], [{ id: 1.5 }]]) {
      fs.writeFileSync(file, JSON.stringify(bad));
      assert.throws(() => loadTodos(file), TodoError, `expected ${JSON.stringify(bad)} to be rejected`);
    }
  });

  test('rethrows filesystem errors other than a missing file', () => {
    // Reading a directory fails with EISDIR, which is not a "no todos yet" case.
    assert.throws(() => loadTodos(dir), (err) => !(err instanceof TodoError) && err.code === 'EISDIR');
  });
});

describe('saveTodos', () => {
  test('round-trips through loadTodos', () => {
    const todos = [
      { id: 1, text: 'a', completed: true, createdAt: '2026-01-01T00:00:00.000Z' },
      { id: 3, text: 'b', completed: false, createdAt: '2026-01-02T00:00:00.000Z' },
    ];
    saveTodos(file, todos);
    assert.deepEqual(loadTodos(file), todos);
  });

