  test('creates a todo with id, text, completed and createdAt', () => {
    const now = new Date('2026-09-30T12:34:56.789Z');
    const todo = addTodo(file, 'Buy groceries', now);

    assert.deepEqual(todo, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-09-30T12:34:56.789Z',
    });
    assert.deepEqual(readRaw(), [todo]);
  });

  test('defaults createdAt to the current time', () => {
    const before = Date.now();
    const todo = addTodo(file, 'Now');
    const after = Date.now();

    const created = Date.parse(todo.createdAt);
    assert.ok(created >= before && created <= after, `${todo.createdAt} not within test window`);
  });

