  test('rejects empty, whitespace-only and non-string text without writing', () => {
    for (const text of ['', '   ', undefined, null, 42]) {
      assert.throws(() => addTodo(file, text), { name: 'TodoError', message: /cannot be empty/ });
    }
    assert.equal(fs.existsSync(file), false);
  });
});

describe('completeTodo', () => {
  test('marks the todo as completed and persists it', () => {
    addTodo(file, 'one');
    addTodo(file, 'two');

    const { todo, changed } = completeTodo(file, 2);

    assert.equal(changed, true);
    assert.equal(todo.completed, true);
    assert.deepEqual(
      readRaw().map((t) => t.completed),
      [false, true]
    );
  });

  test('reports no change for an already completed todo', () => {
    addTodo(file, 'one');
    completeTodo(file, 1);

    const { todo, changed } = completeTodo(file, 1);

    assert.equal(changed, false);
    assert.equal(todo.completed, true);
  });

  test('throws a TodoError for an unknown id', () => {
    addTodo(file, 'one');
    assert.throws(() => completeTodo(file, 99), { name: 'TodoError', message: 'Todo #99 not found' });
  });

  test('throws a TodoError when there are no todos', () => {
    assert.throws(() => completeTodo(file, 1), { name: 'TodoError', message: 'Todo #1 not found' });
  });
});

describe('deleteTodo', () => {
  test('removes only the matching todo and returns it', () => {
    addTodo(file, 'one');
    addTodo(file, 'two');
    addTodo(file, 'three');

    const removed = deleteTodo(file, 2);

    assert.equal(removed.text, 'two');
    assert.deepEqual(
      readRaw().map((t) => [t.id, t.text]),
      [
        [1, 'one'],
        [3, 'three'],
      ]
    );
  });

  test('throws a TodoError for an unknown id and leaves the file untouched', () => {
    addTodo(file, 'one');
    const before = fs.readFileSync(file, 'utf8');

    assert.throws(() => deleteTodo(file, 5), { name: 'TodoError', message: 'Todo #5 not found' });
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });
});

