    const result = run(['delete']);

    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Missing todo id/);
  });

  test('fails when the id does not exist', () => {
    run(['add', 'Keep me']);

    const result = run(['delete', '3']);

    assert.equal(result.code, 1);
