      assert.match(result.stdout, /^Usage: node index\.js <command>/);
      for (const command of ['add', 'list', 'complete', 'delete']) {
        assert.match(result.stdout, new RegExp(`^  ${command}\\b`, 'm'));
      }
    });
  }

  test('fails with usage for an unknown command', () => {
    const result = run(['frobnicate']);

    assert.equal(result.code, 1);
    assert.match(result.stderr, /^Error: Unknown command "frobnicate"/);
    assert.match(result.stderr, /Usage:/);
  });
});

describe('storage', () => {
  test('uses todos.json in the current working directory', () => {
    const sub = path.join(dir, 'project');
    fs.mkdirSync(sub);

    run(['add', 'In subdirectory'], sub);

    assert.equal(fs.existsSync(path.join(sub, 'todos.json')), true);
    assert.equal(fs.existsSync(todosPath()), false);
  });

  test('reports corrupted JSON without overwriting the file', () => {
    fs.writeFileSync(todosPath(), '{oops');

    for (const args of [['list'], ['add', 'x'], ['complete', '1'], ['delete', '1']]) {
      const result = run(args);
      assert.equal(result.code, 1, `${args[0]} should fail`);
      assert.match(result.stderr, /^Error: .*todos\.json is not valid JSON/);
    }
    assert.equal(fs.readFileSync(todosPath(), 'utf8'), '{oops');
  });

  test('reports a todos.json that is not a list of todos', () => {
    fs.writeFileSync(todosPath(), '{"todos": []}');

    const result = run(['list']);

    assert.equal(result.code, 1);
    assert.match(result.stderr, /does not contain a list of todos/);
  });

  test('supports a full add, complete, delete workflow', () => {
    run(['add', 'Buy groceries']);
    run(['add', 'Walk the dog']);
    run(['add', 'Write report']);
    run(['complete', '3']);
    run(['delete', '1']);
    run(['add', 'Call the bank']);

    assert.equal(
      run(['list']).stdout,
      '2. [ ] Walk the dog\n3. [x] Write report\n4. [ ] Call the bank\n'
    );
  });
});
